import { describe, expect, it } from 'vitest'
import { generateEdgeSpeechToken } from './edgeSpeechToken'

// Reference outputs independently generated by edge-tts drm.py at
// ba61d94442c18893f0c4d3c5ad253718b21ab93e, not by this implementation.
const vectors: Array<[number, string]> = [
  [0, '52BC7A17B50DFEC9-28C4394775C8751CD2F6859C030C06DB1489ACAB3B3A7651831FC26895177ED6'],
  [1690000000, '5AFD49CE077AC604-2E6DEB55838D0C292812E6E891CF326168231A743FACD43C30103BCD7BB8A439'],
  [1791774969, '68239906C2A9B491-878517B0F783E8668C41D5AC65C4511E018153D56DD6054C3BBFC89FCDA41027'],
  [1792914599.999, '1DA8399C8CEA5550-59877E6E3AA8284CA97D2C57F6910149A9246F5C7C38FDFF5F3F77D00D6BE019'],
  [1792914600, 'C32D80A8FFBCFACD-443BFC0B127D09B4B99A55B7C0DC29B1AC1B88977667D2B179412BF205234B41'],
  [1792914899.999, 'C32D80A8FFBCFACD-443BFC0B127D09B4B99A55B7C0DC29B1AC1B88977667D2B179412BF205234B41'],
  [1792914900, '159AAF52AAE7D548-B64DFE1199EC474D0FF2842FC67DEDBB45D7148D60F925202495CB1688DBA902'],
  [4102444800, 'DD230DB44FEE2FD7-DA0D4FA797866E36C992FABB81DD2F9DB37EB74D675D63228277003DCD3F9F8C']
]

describe('Edge speech v2 authentication', () => {
  it.each(vectors)('matches the reference token at Unix time %s', (timestamp, expected) => {
    expect(generateEdgeSpeechToken(timestamp)).toBe(expected)
  })

  it.each([NaN, Infinity, -Infinity])('rejects invalid timestamps: %s', (timestamp) => {
    expect(() => generateEdgeSpeechToken(timestamp)).toThrow('finite')
  })
})
